</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
using namespace std;
int main() {
    long long i, j, k, m, n, a, b, x, y;
    float min, mi;
    while (cin >> x >> y >> n) {
        if (y <= n) {
            a = x;
            b = y;
        } else {
            min = 1.0f;
            for (long long i_iter = 1; i_iter <= n; ++i_iter) {
                k = i_iter * x / y;
                mi = (float)x / y - (float)k / i_iter;
                if (mi < min) {
                    min = mi;
                    a = k;
                    b = i_iter;
                }
                mi = (float)(k + 1) / i_iter - (float)x / y;
                if (mi < min) {
                    min = mi;
                    a = k + 1;
                    b = i_iter;
                }
            }
        }
        if (a > b) {
            m = a;
            n = b;
        } else {
            m = b;
            n = a;
        }
        if (n == 0) m = 1;
        else {
            while (n != 0) {
                j = m % n;
                m = n;
                n = j;
            }
        }
        if (j != 1) {
            a /= m;
            b /= m;
        }
        cout << a << "/" << b << endl;
    }
    return 0;
}
</original_code>

